<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('administrator');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$studentId=filter_input(INPUT_POST,'student_id',FILTER_VALIDATE_INT)?:0;$supervisorId=filter_input(INPUT_POST,'supervisor_id',FILTER_VALIDATE_INT)?:0;
 $q=db()->prepare("SELECT u.id,u.department_id,u.first_name,u.last_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND r.name='student' AND u.account_status='active'");$q->execute([$studentId]);$student=$q->fetch();
 $q=db()->prepare("SELECT u.id,u.department_id,u.first_name,u.last_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND r.name='supervisor' AND u.account_status='active'");$q->execute([$supervisorId]);$supervisor=$q->fetch();
 if(!$student||!$supervisor)$error='Select an active student and supervisor.';elseif((int)$student['department_id']!==(int)$supervisor['department_id'])$error='Student and supervisor must belong to the same department.';else{
  try{db()->beginTransaction();db()->prepare('UPDATE student_supervisors SET ended_at=NOW() WHERE student_id=? AND ended_at IS NULL')->execute([$studentId]);db()->prepare('INSERT INTO student_supervisors(student_id,supervisor_id,assigned_by) VALUES(?,?,?)')->execute([$studentId,$supervisorId,$u['id']]);$projectQ=db()->prepare('SELECT p.id,p.status FROM projects p JOIN project_members pm ON pm.project_id=p.id WHERE pm.student_id=? ORDER BY p.created_at DESC LIMIT 1');$projectQ->execute([$studentId]);$existingProject=$projectQ->fetch();$projectId=(int)($existingProject['id']??0);if($projectId){db()->prepare('UPDATE project_supervisors SET ended_at=NOW() WHERE project_id=? AND ended_at IS NULL')->execute([$projectId]);db()->prepare('INSERT INTO project_supervisors(project_id,supervisor_id,assigned_by) VALUES(?,?,?)')->execute([$projectId,$supervisorId,$u['id']]);$approved=db()->prepare("SELECT COUNT(*) FROM project_ideas WHERE project_id=? AND review_status='approved'");$approved->execute([$projectId]);$started=in_array($existingProject['status'],['proposal_submitted','in_progress','correction_required','final_submission','under_evaluation','approved','completed','archived'],true);$nextStatus=$started?$existingProject['status']:((int)$approved->fetchColumn()>0?'supervisor_assigned':'idea_under_review');db()->prepare('UPDATE projects SET status=? WHERE id=?')->execute([$nextStatus,$projectId]);}db()->commit();notify_user($studentId,'Supervisor assigned','The administrator assigned your department supervisor.','success','user',$studentId);notify_user($supervisorId,'Student assigned','A student has been added to your supervision list.','action','user',$studentId);if($projectId)notify_user($supervisorId,'Project supervision assigned','The student has a registered project and project ideas awaiting review.','action','project',$projectId);audit('student_supervisor_assigned','user',$studentId,'Administrator assigned supervisor '.$supervisorId);flash('success','Supervisor assignment saved.');redirect('admin/assignments.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();error_log($e->getMessage());$error='The assignment could not be saved.';}
 }
}
$students=db()->query("SELECT u.id,u.department_id,u.matric_number,u.first_name,u.last_name,d.name department FROM users u JOIN roles r ON r.id=u.role_id JOIN departments d ON d.id=u.department_id WHERE r.name='student' AND u.account_status='active' ORDER BY d.name,u.matric_number")->fetchAll();
$supervisors=db()->query("SELECT u.id,u.first_name,u.last_name,u.staff_number,u.department_id,d.name department FROM users u JOIN roles r ON r.id=u.role_id JOIN departments d ON d.id=u.department_id WHERE r.name='supervisor' AND u.account_status='active' ORDER BY d.name,u.last_name")->fetchAll();
$rows=db()->query("SELECT ss.student_id,ss.supervisor_id,ss.assigned_at,st.matric_number,st.first_name student_first,st.last_name student_last,d.name department,su.first_name supervisor_first,su.last_name supervisor_last,su.staff_number FROM student_supervisors ss JOIN users st ON st.id=ss.student_id JOIN users su ON su.id=ss.supervisor_id JOIN departments d ON d.id=st.department_id WHERE ss.ended_at IS NULL ORDER BY d.name,ss.assigned_at DESC")->fetchAll();
$pageTitle='Supervisor Assignment';$crumbTrail=['Admin','Supervisors','Assignments Portal'];require dirname(__DIR__).'/includes/header.php';
?>
<?php if($error): ?><div role="alert" class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<section class="card p-4 mb-3"><h2 class="section-heading">Assign Supervisor to Student</h2>
<form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="col-lg-6"><label class="form-label" for="student_id">Select Student</label><select class="form-select" name="student_id" id="student_id" required><option value="">Select a student...</option><?php foreach($students as $s): ?><option value="<?= (int)$s['id'] ?>" data-department="<?= (int)$s['department_id'] ?>"><?= e($s['matric_number'].' · '.trim(($s['first_name']??'').' '.($s['last_name']??'')).' · '.$s['department']) ?></option><?php endforeach; ?></select></div><div class="col-lg-6"><label class="form-label" for="supervisor_id">Select Supervisor</label><select class="form-select" name="supervisor_id" id="supervisor_id" required><option value="">Select a supervisor...</option><?php foreach($supervisors as $s): ?><option value="<?= (int)$s['id'] ?>" data-department="<?= (int)$s['department_id'] ?>"><?= e(trim(($s['first_name']??'').' '.($s['last_name']??'')).' · '.$s['department'].' · '.$s['staff_number']) ?></option><?php endforeach; ?></select><div class="form-text">Only supervisors in the student's department can be assigned. Previous assignments remain in the history.</div></div><div class="col-12 form-actions mt-2"><a class="btn btn-outline-primary" href="<?= e(url('admin/assignments.php')) ?>">Cancel</a><button class="btn btn-danger">Assign Supervisor</button></div></form></section>
<section class="card p-4"><div class="section-row mb-3"><h2 class="section-heading mb-0">Current Supervision Assignments</h2><label class="search-box m-0"><?= ui_icon('search') ?><input type="search" class="form-control" placeholder="Search assignments..." aria-label="Search assignments" data-live-filter="#assignTable tbody tr"></label></div><div class="table-responsive"><table class="table table-soft" id="assignTable"><thead><tr><th>Student</th><th>Matric no</th><th>Supervisor</th><th>Department</th><th>Assigned date</th></tr></thead><tbody>
