<?php if(!$rows): ?><tr><td colspan="5"><div class="empty-state">No active supervisor assignments.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span class="text-muted">Showing <?= count($rows) ?> active record<?= count($rows)===1?'':'s' ?></span></div></section>
